fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    // Helper function to compute prefix sum S(k)
    // S(k) = k/2 if k even
    // S(k) = -(k+1)/2 if k odd
    fn prefix_sum(k: i8) -> i8 {
        if k == 0 {
            0
        } else if k % 2 == 0 {
            k / 2
        } else {
            -((k as i16 + 1) / 2) as i8
        }
    }

    queries
        .into_iter()
        .map(|(l, r)| {
            // l >= 1 guaranteed, so l-1 >= 0 fits in i8 range
            prefix_sum(r) - prefix_sum(l - 1)
        })
        .collect()
}